import pandas as pd
import numpy as np

dfs = []
for i in range(1, 10):
    col_name = f'experiment_{i}_csv'
    if col_name in dir():
        try:
            dfs.append(pd.read_csv(locals()[col_name]))
        except Exception as e:
            pass

if dfs:
    df = pd.concat(dfs, ignore_index=True)
    print("Columns:", df.columns.tolist())
    print("\nShape:", df.shape)
    print("\nDescribe:\n", df.describe().round(2))

    # Find yield and treatment columns
    yield_col = [c for c in df.columns if 'yield' in c.lower() or c == 'CropYield']
    treat_col = [c for c in df.columns if 'treat' in c.lower() or 'action' in c.lower() or 'dose' in c.lower()]

    if yield_col:
        y = yield_col[0]
        print(f"\nCorrelations with {y}:")
        print(df.corr(numeric_only=True)[y].sort_values(ascending=False))

        print(f"\nMean {y} by Treatment:")
        if treat_col:
            t = treat_col[0]
            print(df.groupby(t)[y].agg(['mean','std','count']).round(2))
    else:
        print("No yield column found.")
else:
    print("No dataframes loaded.")

